// Material DestinationEnvironmentComposite (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_trafficSize: vec2f,
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_page0: texture_2d<f32>;
@group(2) @binding(2) var tex_page1: texture_2d<f32>;
@group(2) @binding(3) var tex_traffic: texture_2d<f32>;
@group(2) @binding(4) var material_sampler: sampler;

fn environment_composite_texel(page0: texture_2d<f32>, sampler0: sampler,
  page1: texture_2d<f32>, sampler1: sampler,
  traffic: texture_2d<f32>, trafficSampler: sampler,
  coord: vec2f, kind: f32, trafficSize: vec2f) -> vec4f {
  if (kind > 1.5) {
    let point = (floor(coord * trafficSize) + vec2f(0.5)) / trafficSize;
    return textureSampleLevel(traffic, trafficSampler, point, 0.0);
  }
  if (kind > 0.5) {
    return textureSampleLevel(page1, sampler1, coord, 0.0);
  }
  return textureSampleLevel(page0, sampler0, coord, 0.0);
}
const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: f32 = in.uv1.x;
  let v1: vec4f = environment_composite_texel(tex_page0, material_sampler, tex_page1, material_sampler, tex_traffic, material_sampler, in.uv, v0, material.p_trafficSize);
  let v2: vec3f = v1.xyz;
  let v3: f32 = v1.w;
  out.base_color = v2;
  out.alpha = v3;
  return out;
}
